import * as THREE from 'three/webgpu';
import { GSAP } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const disposables = [];

  // ===== TORUS KNOT WITH BRUSHED-METAL PBR =====
  const torusKnotGeometry = new THREE.TorusKnotGeometry(0.7, 0.22, 220, 36);

  const roughnessMap = ctx.textureLoader.load(
    '/prism-assets/chrome/brushed-metal.map.png'
  );
  roughnessMap.colorSpace = THREE.LinearSRGBColorSpace;

  const torusKnotMaterial = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color(0xe8ecf2),
    metalness: 0.55,
    roughness: 0.55,
    roughnessMap,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
    anisotropy: 0.9,
    anisotropyRotation: Math.PI / 2,
    envMapIntensity: 0.7,
  });

  const torusKnot = new THREE.Mesh(torusKnotGeometry, torusKnotMaterial);
  torusKnot.position.y = 0.4;
  group.add(torusKnot);
  disposables.push(torusKnotGeometry, torusKnotMaterial, roughnessMap);

  // ===== PEDESTAL CYLINDER =====
  const pedestalGeometry = new THREE.CylinderGeometry(1.1, 1.1, 0.5, 64);
  const pedestalMaterial = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color(0x14141a),
    metalness: 0.35,
    roughness: 0.7,
  });

  const pedestal = new THREE.Mesh(pedestalGeometry, pedestalMaterial);
  pedestal.position.y = -0.35;
  group.add(pedestal);
  disposables.push(pedestalGeometry, pedestalMaterial);

  // ===== CONTACT SHADOW PLANE =====
  const shadowGeometry = new THREE.CircleGeometry(1.5, 64);
  const shadowMaterial = new THREE.MeshBasicMaterial({
    color: new THREE.Color(0x000000),
    transparent: true,
    opacity: 0.6,
    depthWrite: false,
  });

  const shadow = new THREE.Mesh(shadowGeometry, shadowMaterial);
  shadow.position.y = -0.36;
  shadow.rotation.x = -Math.PI / 2;
  shadow.renderOrder = -1;
  group.add(shadow);
  disposables.push(shadowGeometry, shadowMaterial);

  // ===== BACKDROP PLANE WITH VERTICAL GRADIENT =====
  const backdropGeometry = new THREE.PlaneGeometry(7, 6);

  const width = 256;
  const height = 256;
  const pixelData = new Uint8Array(width * height * 3);

  const gradientStops = [
    { pos: 0.0, r: 0x0b, g: 0x0b, b: 0x10 },
    { pos: 0.7, r: 0x10, g: 0x10, b: 0x17 },
    { pos: 1.0, r: 0x16, g: 0x16, b: 0x1d },
  ];

  for (let y = 0; y < height; y++) {
    const t = y / height;
    let color;

    if (t <= 0.7) {
      const s = t / 0.7;
      const c0 = gradientStops[0];
      const c1 = gradientStops[1];
      color = {
        r: Math.round(c0.r + (c1.r - c0.r) * s),
        g: Math.round(c0.g + (c1.g - c0.g) * s),
        b: Math.round(c0.b + (c1.b - c0.b) * s),
      };
    } else {
      const s = (t - 0.7) / 0.3;
      const c1 = gradientStops[1];
      const c2 = gradientStops[2];
      color = {
        r: Math.round(c1.r + (c2.r - c1.r) * s),
        g: Math.round(c1.g + (c2.g - c1.g) * s),
        b: Math.round(c1.b + (c2.b - c1.b) * s),
      };
    }

    for (let x = 0; x < width; x++) {
      const idx = (y * width + x) * 3;
      pixelData[idx] = color.r;
      pixelData[idx + 1] = color.g;
      pixelData[idx + 2] = color.b;
    }
  }

  const backdropTexture = new THREE.DataTexture(
    pixelData,
    width,
    height,
    THREE.RGBFormat
  );
  backdropTexture.magFilter = THREE.LinearFilter;
  backdropTexture.minFilter = THREE.LinearFilter;
  backdropTexture.needsUpdate = true;

  const backdropMaterial = new THREE.MeshBasicMaterial({ map: backdropTexture });
  const backdrop = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -3;
  group.add(backdrop);
  disposables.push(backdropGeometry, backdropMaterial, backdropTexture);

  // ===== LIGHTING =====
  const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 2, 2);
  keyLight.target.position.set(0, 0.4, 0);

  group.add(ambientLight);
  group.add(keyLight);
  group.add(keyLight.target);

  // ===== TEXT RENDERING VIA FONT ATLAS =====
  let headlineTextMesh = null;
  let captionTextMesh = null;

  if (ctx.fontAtlas && typeof ctx.fontAtlas.createTextMesh === 'function') {
    try {
      headlineTextMesh = ctx.fontAtlas.createTextMesh({
        text: 'Material study 03',
        fontSize: 68,
        fontFamily: 'Lora',
        fontWeight: 600,
        color: 0xe8ecf2,
      });

      if (headlineTextMesh) {
        headlineTextMesh.position.set(0, -1.2, 0.1);
        group.add(headlineTextMesh);
      }
    } catch (e) {
      console.warn('Headline text rendering failed:', e);
    }

    try {
      captionTextMesh = ctx.fontAtlas.createTextMesh({
        text: 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT',
        fontSize: 18,
        fontFamily: 'JetBrains Mono',
        fontWeight: 400,
        color: 0xff2a38,
        letterSpacing: 0.08,
      });

      if (captionTextMesh) {
        captionTextMesh.position.set(0, -1.6, 0.1);
        group.add(captionTextMesh);
      }
    } catch (e) {
      console.warn('Caption text rendering failed:', e);
    }
  }

  // ===== APPLY ORBIT PRIMITIVE =====
  if (ctx.primitives && typeof ctx.primitives.orbit === 'function') {
    ctx.primitives.orbit(torusKnot, { speed: 0.1, radius: 0.4 });
  }

  // ===== CLEANUP =====
  group.userData.cleanup = () => {
    disposables.forEach((item) => {
      if (item && typeof item.dispose === 'function') {
        item.dispose();
      }
    });

    if (headlineTextMesh) {
      if (headlineTextMesh.geometry)
        headlineTextMesh.geometry.dispose();
      if (headlineTextMesh.material)
        headlineTextMesh.material.dispose();
    }

    if (captionTextMesh) {
      if (captionTextMesh.geometry) captionTextMesh.geometry.dispose();
      if (captionTextMesh.material) captionTextMesh.material.dispose();
    }

    GSAP.killTweensOf([torusKnot, group]);
  };

  return group;
}
